import {Injectable} from 'angular2/core';
import {Observable} from 'rxjs/Observable';
import {Subject} from "rxjs/Subject";

@Injectable()
export class UserService {

    public constructor(private http: Http) {
        Observable.fromEvent(this.http.get('users')).subscribe(data => {
            if (data && data.length > 0) {
                this.user = data[0];
                return Observable.of(this.user);
            } else if (data && data.length === 0) {
                console.log("User not found.");
                return new Observable(observer => {
                    let user: User = this.user.getUsers();
                    Observable.fromEvent(this.http.get('users'))
                        .pipe(takeUntil(this.unsubscribe))
                        .subscribe(data => {
                            observer.next(data);
                        });
                });
            }
        })
    }

    private subscribeToUser(user: User, user: User = null) {
        let userService = this.userService.getUsers(user);
        userService.subscribe(user => {
            this.user = user;
            if (user && user.isFlight) {
                this.userService.getFlightUser(user)
                    .subscribe(data => {
                        this.user = data[0];
                        observer.next(data);
                    });
            } else if (user && user.isFlight) {
                console.log("User not found.");
                this.userService.getUser(user)
                    .subscribe(data => {
                        this.user = data[0];
                        observer.next(data);
                    });
            }
        });
    }
}

