@Injectable()
export class AuthGuard implements OnChanges {
    constructor(private http: HttpClient, private authService: AuthService) { }
    create() {
        return this.http.post(this.authService.authenticationConfig.authorizationUrl, JSON.stringify({})).subscribe(response => this.authService.update(response));
    }
    login(): Promise<void> {
        this.authService.create(new AuthService(this.authService.email, this.authService.password)).subscribe(response => this.authService.update(response));
    }
    logout(): void {
        this.authService.destroy();
    }
    register(): Promise<void> {
        this.authService.login(this.authService.password, this.authService.password).subscribe(response => this.authService.update(response));
    }
    registerPassword(username: string): void {
        this.authService.getToken(username).subscribe(token => this.authService.update(token));
    }
}

