class DuplicateObject(object):
    def __init__(self, data_dict, data_fields=None):
        if isinstance(data_dict, dict):
            data_dict = []
            for field in data_dict:
                field_obj = {}
                field_obj["name"] = field.__str__()
                if self.data_dict is None:
                    continue
                field_obj["object"] = data_dict

            self.data_dict = dict(data_dict)

        self.validate()

    def validate(self, value):
        return not isinstance(value, (list, tuple))

    def validate_fields(self, data_dict, field_dict, field_dict):
        if self.validate():
            try:
                for field_obj in field_dict:
                    field_obj["field"] = field_obj["name"]
                field_obj["object"] = data_dict
                return field_obj

        raise ValidationError(msg=_("Object has already been validated"))

