def format_response(search_result):
    # requires search_result to be a dictionary
    res = search_result.pop('response')
    code = 200

    if res.get('status') is None:
        response = search_result
    elif res.get('status') == 404:
        response = {
            'status': 404,
            'error': {
                'message': 'Not Found Error'
            }
        }
        code = 404
    elif res.get('status') == 400:
        response = {
            'status': 400,
            'error': res.get('error')
        }
        code = 400
    else:
        response = {
            'status': 500,
            'error': {
                'message': 'Server Error'
            }
        }
        code = 500
    return response, code


class FCEByID(Resource):
    def get(self, courseid):
        result = search.get_fce_by_id(courseid, size=300)
        return format_response(result)


class FCEByInstructor(Resource):
    @utils.word_limit
    def get(self, instructor):
        result = search.get_fce_by_instructor(instructor, size=300)
        return format_response(result)

''' Uses http://omnidator.appspot.com/ to extract schema.org metadata '''
from metaextractor import BasePlugin 
import requests

class Extractor(BasePlugin):
    def extract(self, url, **kwargs):
        rsp = requests.get("http://omnidator.appspot.com/microdata/json/?url="+url)
        if rsp.ok:
            js = rsp.json()
            ret = { 'jsonld' : rsp.json() }
            if js.has_key("@") and len(js["@"]) and js["@"][0].has_key("a") and "schema.org/Article" in js["@"][0]["a"]:
                ret['title'] = js["@"][0]["http://schema.org/Article#headline name"].strip()
                ret['image_url'] = js["@"][0]["http://schema.org/Article#image"].replace("<","").replace(">","")
            return ret
        else:
            return {}

from tests.models_tests import ModelsTestBase
from test_models.core import Language
from tests import dbhelper
from sqlalchemy.exc import IntegrityError


class TestLanguageModel(ModelsTestBase):

    def test_00_init(self):
        assert Language

    def test_01_populate(self):
        dbhelper.add(Language(lang='en', name='English'), self.db)
        dbhelper.add(Language(lang='en-us', name='English US'), self.db)
        dbhelper.add(Language(lang='es', name='Espanol'), self.db)
        dbhelper.add(Language(lang='fr', name='French'), self.db)

        # Duplicate entry
        try:
            dbhelper.add(Language(lang='fr', name='French'), self.db)
            assert False, 'Expected IntegrityError'
        except IntegrityError:
            pass

        assert Language.query.count() == 4

    def test_02_repr_method(self):
        languages = Language.query.all()

        for language in languages:
            assert str(language.id) in str(language)
            assert language.lang in str(language)
            assert language.name in str(language)

    def test_04_languages_lang_name_present(self):
        for language in Language.query.all():
            assert (language.lang is not None and language.lang is not '')
            assert (language.name is not None and language.name is not '')

    def test_05_languages_unique(self):
        assert Language.query.filter(Language.lang == 'en').count() == 1
        assert Language.query.filter(Language.lang == 'en').first().name == 'English'

